/*
 * Deterministic parts of a slice block — generated by `prototype.mjs status`, so the agent only writes what needs judgment
 * (decide / evolve / process and wiring the screen to hooks). Shared by the platform skill and the local prototype.
 *
 *   specsOf(slice, specs)   the slice's `specs` array (every scenario and storyline, Step 4's table) as data
 *   htmlToJsx(html)         one HTML page → JSX (class→className, style strings→objects, void elements closed, handlers dropped)
 *   skeleton(...)           the block file: script tag with hash, GENERATED_SPECS, one component per HTML page, a defineSlice stub
 *
 * Anything the generator cannot decide is left as `@@TODO` — `assemble` refuses a block that still contains one.
 */

const VOID = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'source', 'track', 'wbr']);
const ATTR = {
  class: 'className', for: 'htmlFor', tabindex: 'tabIndex', colspan: 'colSpan', rowspan: 'rowSpan', readonly: 'readOnly',
  maxlength: 'maxLength', minlength: 'minLength', autocomplete: 'autoComplete', autofocus: 'autoFocus', contenteditable: 'contentEditable',
  crossorigin: 'crossOrigin', enctype: 'encType', formaction: 'formAction', frameborder: 'frameBorder', srcset: 'srcSet',
  cellpadding: 'cellPadding', cellspacing: 'cellSpacing', datetime: 'dateTime', novalidate: 'noValidate', spellcheck: 'spellCheck',
  'accept-charset': 'acceptCharset', 'stroke-width': 'strokeWidth', 'stroke-linecap': 'strokeLinecap', 'stroke-linejoin': 'strokeLinejoin',
  'fill-rule': 'fillRule', 'clip-rule': 'clipRule', 'clip-path': 'clipPath', viewbox: 'viewBox', 'stop-color': 'stopColor',
};
const BOOLEAN = new Set(['checked', 'disabled', 'selected', 'readonly', 'required', 'multiple', 'hidden', 'autofocus', 'open', 'novalidate']);

const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const slug = (s) => String(s || '').replace(/[^A-Za-z0-9]+(.)?/g, (_, c) => (c || '').toUpperCase()).replace(/^[^A-Za-z]+/, '') || 'Screen';
export const pascal = (s) => { const x = slug(s); return x.charAt(0).toUpperCase() + x.slice(1); };

function styleObject(css) {
  const parts = css.split(';').map((d) => d.trim()).filter(Boolean).map((d) => {
    const i = d.indexOf(':');
    if (i < 0) return null;
    const k = d.slice(0, i).trim();
    const v = d.slice(i + 1).trim();
    const key = k.startsWith('--') ? JSON.stringify(k) : camel(k.replace(/^-ms-/, 'ms-'));
    return `${key}: ${JSON.stringify(v)}`;
  }).filter(Boolean);
  return `{{ ${parts.join(', ')} }}`;
}

function attrsToJsx(raw) {
  const out = [];
  const re = /([^\s=/"'<>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  for (let m; (m = re.exec(raw)); ) {
    const name = m[1];
    const val = m[2] ?? m[3] ?? m[4];
    const lower = name.toLowerCase();
    if (lower.startsWith('on')) continue; // inline handlers: the page sanitizer strips them, the block wires its own
    if (lower === 'style') { if (val) out.push(`style=${styleObject(val)}`); continue; }
    const key = ATTR[lower] || (lower.startsWith('data-') || lower.startsWith('aria-') ? lower : /^[a-z]+$/.test(lower) ? lower : camel(name));
    if (val === undefined) out.push(BOOLEAN.has(lower) ? `${key}` : `${key}={true}`);
    else if (lower === 'value' || lower === 'checked') out.push(`${lower === 'value' ? 'defaultValue' : 'defaultChecked'}=${JSON.stringify(val)}`);
    else out.push(`${key}=${JSON.stringify(val.replace(/&quot;/g, '"').replace(/&amp;/g, '&'))}`);
  }
  return out.length ? ' ' + out.join(' ') : '';
}

/** One HTML page (document or fragment) → a JSX expression body (single root). */
export function htmlToJsx(html) {
  let src = String(html || '');
  const body = src.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
  if (body) src = body[1];
  src = src.replace(/<!--[\s\S]*?-->/g, '').replace(/<script\b[\s\S]*?<\/script>/gi, '').replace(/<style\b[\s\S]*?<\/style>/gi, '');
  const out = [];
  const re = /<(\/?)([a-zA-Z][\w:-]*)((?:"[^"]*"|'[^']*'|[^>"'])*?)(\/?)>|([^<]+)|(<)/g;
  const stack = [];
  for (let m; (m = re.exec(src)); ) {
    if (m[5] !== undefined) {
      out.push(m[5].replace(/[{}]/g, (c) => `{'${c}'}`).replace(/&nbsp;/g, ' '));
    } else if (m[6]) {
      out.push('&lt;');
    } else if (m[1]) {
      const tag = m[2].toLowerCase();
      if (VOID.has(tag)) continue;
      const at = stack.lastIndexOf(tag);
      if (at < 0) continue;
      while (stack.length > at) out.push(`</${stack.pop()}>`);
    } else {
      const tag = m[2].toLowerCase() === m[2] ? m[2] : m[2];
      const lower = tag.toLowerCase();
      const attrs = attrsToJsx(m[3] || '');
      if (VOID.has(lower) || m[4]) out.push(`<${tag}${attrs} />`);
      else { out.push(`<${tag}${attrs}>`); stack.push(lower === tag ? tag : tag); }
    }
  }
  while (stack.length) out.push(`</${stack.pop()}>`);
  return out.join('').trim();
}

// ── specs ───────────────────────────────────────────────────────────────────

const kindOf = (step) => String(step.type || '').replace(/^SPEC_/, '').toUpperCase();

/** Typed value of a step field example: numbers/booleans stay, JSON-looking strings of lists/objects are parsed. */
function typed(v) {
  if (typeof v !== 'string') return v;
  const t = v.trim();
  if (t === 'true' || t === 'false') return t === 'true';
  if (t !== '' && /^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  if (/^[[{]/.test(t)) { try { return JSON.parse(t); } catch { /* keep the text */ } }
  return v;
}

const dataOf = (step) => Object.fromEntries((step.fields || []).filter((f) => f.name && f.example !== undefined && f.example !== '').map((f) => [f.name, typed(f.example)]));
const nameOf = (step) => String(step.title || '').replace(/\s+/g, '');
const eventOf = (step) => ({ type: nameOf(step), data: dataOf(step) });

/** The slice's specs: every GWT scenario and storyline as a spec entry (SKILL.md Step 4 table). `needs` lists what only a person/agent can add. */
export function specsOf(slice, specSlice) {
  const specs = [];
  const needs = [];
  const automation = (slice.processors || [])[0];
  for (const s of (specSlice && specSlice.specifications) || []) {
    const then = s.then || [];
    const given = (s.given || []).filter((x) => kindOf(x) === 'EVENT').map(eventOf);
    const err = then.find((x) => kindOf(x) === 'ERROR');
    const when = (s.when || []).find((x) => kindOf(x) === 'COMMAND');
    const rm = then.find((x) => kindOf(x) === 'READMODEL') || (s.when || []).find((x) => kindOf(x) === 'READMODEL');
    const cmds = then.filter((x) => kindOf(x) === 'COMMAND');
    if (when && err) specs.push({ title: s.title, kind: 'command', given, when: { type: nameOf(when), data: dataOf(when) }, error: err.description || err.title });
    else if (when) specs.push({ title: s.title, kind: 'command', given, when: { type: nameOf(when), data: dataOf(when) }, then: then.filter((x) => kindOf(x) === 'EVENT').map(eventOf) });
    else if (rm) specs.push({ title: s.title, kind: 'readmodel', readModel: nameOf(rm), given, expect: s.expectEmptyList ? [] : Array.isArray(s.examples) ? s.examples.map((r) => (r && typeof r === 'object' ? Object.fromEntries(Object.entries(r).map(([k, v]) => [k, typed(v)])) : r)) : [] });
    else if (cmds.length && automation) specs.push({ title: s.title, kind: 'automation', automation: String(automation.title).replace(/\s+/g, ''), given, expectCommands: cmds.map((c) => ({ type: nameOf(c), data: dataOf(c) })) });
    else needs.push(`scenario "${s.title}" has no shape the generator knows — write its spec by hand`);
  }
  for (const sl of (specSlice && specSlice.storylines) || []) {
    const given = [];
    for (const beat of sl.elements || []) {
      const k = kindOf(beat);
      if (k === 'EVENT') given.push(eventOf(beat));
      else if (k === 'COMMAND') specs.push({ title: `${sl.title}: ${beat.title}`, kind: 'command', given: [...given], when: { type: nameOf(beat), data: dataOf(beat) }, then: [] });
      else if (k === 'READMODEL' && Array.isArray(beat.examples) && beat.examples.length) specs.push({ title: `${sl.title}: ${beat.title}`, kind: 'readmodel', readModel: nameOf(beat), given: [...given], expect: beat.examples });
    }
    if (!(sl.elements || []).length) needs.push(`storyline "${sl.title}" is empty`);
  }
  return { specs, needs };
}

// ── the block skeleton ──────────────────────────────────────────────────────

const lit = (v) => JSON.stringify(v, null, 2).replace(/\n/g, '\n');

/**
 * The block file of one flagged slice. `screens` = the slice's screen nodes ({ title, node }) from status; `keep` = the previous block's text
 * for a changed slice is NOT used here — a changed slice's old block is kept by status and patched by the agent, skeletons are for new slices.
 */
export function skeleton({ slice, hash, order, specSlice, screens }) {
  const { specs, needs } = specsOf(slice, specSlice);
  const parts = [];
  const todos = [];
  const screenEntries = [];
  (screens || []).forEach((s, i) => {
    const comp = `Screen${pascal(s.title)}${i + 1}`;
    if (s.pages && s.pages.length) {
      const pageNames = s.pages.map((p, n) => {
        const name = s.pages.length > 1 ? `${comp}Page${n + 1}` : comp;
        const html = typeof p === 'string' ? p : p.html || p.content || '';
        parts.push(`function ${name}() {\n  return (\n    <>\n${htmlToJsx(html)}\n    </>\n  );\n}`);
        return name;
      });
      if (pageNames.length > 1) {
        parts.push(`function ${comp}() {\n  const pages = [${pageNames.join(', ')}];\n  const [page, setPage] = React.useState(0);\n  const Page = pages[page];\n  return <Page next={() => setPage(Math.min(page + 1, pages.length - 1))} />;\n}`);
      }
      todos.push(`${comp}: markup is the whole page translated 1:1 — cut it to this slice's region (marks decide when the screen is shared), replace sample data with useReadModel / useCommand, wire the buttons`);
      screenEntries.push(`    ${JSON.stringify(s.title)}: { actor: ${JSON.stringify(s.lane || 'User')}, part: ${comp} },`);
    } else {
      todos.push(`screen "${s.title}" is a sketch or has no pages — write its part by hand (sketch elements are in .work/data/${slice.id}.json)`);
    }
  });
  const cmdStubs = (slice.commands || []).filter((c) => !c.elementCopy).map((c) => `    ${String(c.title).replace(/\s+/g, '')}: { decide(history, cmd, ctx) { /* @@TODO */ } },`);
  const rmStubs = (slice.readmodels || []).filter((c) => !c.elementCopy).map((c) => `    ${String(c.title).replace(/\s+/g, '')}: { initial: () => null, evolve(state, e) { /* @@TODO */ return state; } },`);
  const autoStubs = (slice.processors || []).map((a) => `    ${String(a.title).replace(/\s+/g, '')}: { readModel: '@@TODO', trigger: 'auto', todo: (items) => items, process: (item) => ({ command: { type: '@@TODO', data: {} } }) },`);
  const head = `<script type="text/plain" data-em-slice="${slice.id}" data-em-title="${String(slice.title).replace(/"/g, '&quot;')}" data-em-hash="${hash}">`;
  const body = [
    `// GENERATED by prototype.mjs status — specs and screen markup. Edit in place and fill every open marker (assemble refuses a block that still has one).`,
    ...(needs.length ? needs.map((n) => `// NEEDS: ${n}`) : []),
    ...todos.map((t) => `// TODO: ${t}`),
    `const GENERATED_SPECS = ${lit(specs)};`,
    ...parts,
    [
      `EMRuntime.defineSlice({`,
      `  id: ${JSON.stringify(slice.id)},`,
      `  title: ${JSON.stringify(slice.title)},`,
      `  order: ${order},`,
      cmdStubs.length ? `  commands: {\n${cmdStubs.join('\n')}\n  },` : '',
      rmStubs.length ? `  readModels: {\n${rmStubs.join('\n')}\n  },` : '',
      autoStubs.length ? `  automations: {\n${autoStubs.join('\n')}\n  },` : '',
      `  specs: GENERATED_SPECS,`,
      screenEntries.length ? `  screens: {\n${screenEntries.join('\n')}\n  },` : '',
      `});`,
    ].filter(Boolean).join('\n'),
  ].filter(Boolean).join('\n\n');
  return { block: `${head}\n${body}\n</script>\n`, specCount: specs.length, needs, todos };
}
